INSERT INTO `assignments` VALUES (1,1,'Trình bày về Promise và async/await','Viết bài (150-300 từ) giải thích Promise, async/await và cho ví dụ.','Giải thích Promise; trạng thái pending fulfilled rejected; async await; xử lý lỗi try catch; ví dụ minh họa',10,'2026-11-03 16:59:00','2026-09-12 13:29:00'),(2,1,'So sánh var, let và const','Trình bày điểm khác nhau giữa var, let và const kèm ví dụ.','phạm vi khối; hoisting; gán lại giá trị; khai báo lại; ví dụ',10,'2026-10-15 16:59:00','2026-09-10 14:07:00'),(3,2,'Thiết kế REST API quản lý sinh viên','Mô tả các endpoint CRUD, phương thức HTTP, mã trạng thái và cách xác thực.','Endpoint CRUD; phương thức GET POST PUT DELETE; mã trạng thái HTTP; middleware; xác thực JWT',10,'2026-10-30 16:59:00','2026-09-21 08:29:00'),(4,3,'Giải thích vòng đời component với Hooks','Trình bày cách useState và useEffect hoạt động, cho ví dụ gọi API.','useState; useEffect; mảng phụ thuộc; render lại; dọn dẹp; ví dụ gọi API',10,'2026-10-27 16:59:00','2026-09-30 07:59:00'),(5,4,'Thiết kế CSDL quản lý thư viện','Thiết kế các bảng, khóa chính, khóa ngoại cho hệ thống quản lý thư viện và viết 3 câu truy vấn mẫu.','bảng; khóa chính; khóa ngoại; quan hệ; chuẩn hóa; truy vấn JOIN',10,'2026-11-01 16:59:00','2026-09-12 01:02:00'),(6,4,'Viết truy vấn thống kê','Viết truy vấn thống kê số sách mượn theo tháng dùng GROUP BY.','SELECT; GROUP BY; COUNT; JOIN; ORDER BY',10,'2026-10-10 16:59:00','2026-09-19 01:53:00'),(7,5,'Phân biệt Flexbox và Grid','Trình bày khi nào nên dùng Flexbox, khi nào dùng Grid, có ví dụ.','flexbox; grid; một chiều; hai chiều; responsive; ví dụ',10,'2026-11-09 16:59:00','2026-09-21 12:11:00'),(8,7,'Phân tích độ phức tạp thuật toán sắp xếp','So sánh độ phức tạp của sắp xếp nổi bọt, sắp xếp trộn và sắp xếp nhanh.','Big O; nổi bọt O(n^2); trộn O(n log n); nhanh; trường hợp xấu nhất; bộ nhớ',10,'2026-10-29 16:59:00','2026-09-24 08:31:00'),(9,8,'Đề xuất ứng dụng AI cho giáo dục','Đề xuất một tính năng AI cho hệ thống học tập, mô tả prompt, dữ liệu đầu vào, đầu ra và rủi ro.','tính năng AI; prompt; đầu vào; đầu ra JSON; rủi ro; kiểm duyệt con người',10,'2026-11-14 16:59:00','2026-09-25 04:38:00');
/*!40000 ALTER TABLE `assignments` ENABLE KEYS */;
