INSERT INTO `courses` VALUES (1,'Lập trình JavaScript cơ bản','Nắm vững cú pháp, kiểu dữ liệu, hàm, mảng, đối tượng và xử lý bất đồng bộ trong JavaScript.','Lập trình','beginner',2,1,'2026-08-12 14:39:00'),(2,'Node.js & Express xây dựng REST API','Xây dựng REST API với Node.js, Express, middleware, xác thực JWT và kết nối MySQL.','Backend','intermediate',6,1,'2026-08-17 01:01:00'),(3,'React từ cơ bản đến nâng cao','Component, props, state, hooks, React Router và gọi API trong ứng dụng React.','Frontend','intermediate',7,1,'2026-07-12 14:53:00'),(4,'Cơ sở dữ liệu MySQL','Thiết kế CSDL quan hệ, chuẩn hóa, truy vấn SQL, JOIN, chỉ mục và giao dịch.','Cơ sở dữ liệu','beginner',2,1,'2026-08-11 12:26:00'),(5,'HTML & CSS cho người mới','Xây dựng trang web tĩnh với HTML5 ngữ nghĩa, CSS Flexbox, Grid và thiết kế responsive.','Frontend','beginner',6,1,'2026-08-16 12:16:00'),(6,'Git & GitHub làm việc nhóm','Quản lý phiên bản mã nguồn với Git, làm việc nhóm với branch, pull request trên GitHub.','Công cụ','beginner',7,1,'2026-07-30 05:17:00'),(7,'Cấu trúc dữ liệu và giải thuật','Độ phức tạp thuật toán, mảng, danh sách liên kết, ngăn xếp, hàng đợi, cây, đồ thị, sắp xếp và tìm kiếm.','Lập trình','advanced',2,1,'2026-08-02 08:21:00'),(8,'Ứng dụng AI trong phát triển phần mềm','Tích hợp mô hình ngôn ngữ lớn (Groq, Gemini, GPT-4o) vào ứng dụng: prompt engineering, JSON output, đánh giá kết quả.','Trí tuệ nhân tạo','advanced',6,1,'2026-07-29 04:40:00'),(9,'Docker & triển khai ứng dụng','Đóng gói ứng dụng bằng Docker và triển khai lên máy chủ. (Đang soạn)','Công cụ','intermediate',2,0,'2026-10-20 21:24:53');
/*!40000 ALTER TABLE `courses` ENABLE KEYS */;
UNLOCK TABLES;

