INSERT INTO `learning_paths` VALUES (1,3,'Trở thành lập trình viên Fullstack JavaScript','{\"summary\":\"Lộ trình 4 bước hướng tới mục tiêu: Trở thành lập trình viên Fullstack JavaScript.\",\"steps\":[{\"order\":1,\"courseId\":2,\"title\":\"Node.js & Express xây dựng REST API\",\"weeks\":2,\"reason\":\"Bạn đã hoàn thành 60% — hãy tiếp tục để nắm vững backend.\"},{\"order\":2,\"courseId\":3,\"title\":\"React từ cơ bản đến nâng cao\",\"weeks\":2,\"reason\":\"Frontend React là nửa còn lại của Fullstack.\"},{\"order\":3,\"courseId\":4,\"title\":\"Cơ sở dữ liệu MySQL\",\"weeks\":2,\"reason\":\"Cơ sở dữ liệu cần cho mọi ứng dụng web.\"},{\"order\":4,\"courseId\":8,\"title\":\"Ứng dụng AI trong phát triển phần mềm\",\"weeks\":3,\"reason\":\"Ứng dụng AI giúp sản phẩm nổi bật hơn.\"}],\"tips\":[\"Học đều 45–60 phút mỗi ngày.\",\"Làm dự án nhỏ sau mỗi khóa.\",\"Hỏi Trợ lý AI khi gặp khó khăn.\"],\"provider\":\"mock\"}','2026-10-17 15:56:00');
