LOCK TABLES `lessons` WRITE;
/*!40000 ALTER TABLE `lessons` DISABLE KEYS */;
INSERT INTO `lessons` VALUES (1,1,'Giới thiệu JavaScript','JavaScript là ngôn ngữ lập trình chạy trên trình duyệt và máy chủ. Nó được dùng để tạo trang web tương tác.\nBiến được khai báo bằng let và const. Dùng const cho giá trị không gán lại, let cho giá trị thay đổi.\nKiểu dữ liệu nguyên thủy gồm string, number, boolean, null, undefined, bigint và symbol.','https://www.youtube.com/watch?v=W6NZfCO5SIk',1,11),(2,1,'Toán tử và câu lệnh điều kiện','Toán tử so sánh === kiểm tra cả giá trị và kiểu dữ liệu, nên dùng thay cho ==.\nCâu lệnh if, else if, else và switch giúp rẽ nhánh chương trình.\nToán tử ba ngôi điều_kiện ? a : b là cách viết gọn của if else.',NULL,2,25),(3,1,'Vòng lặp','Vòng lặp for lặp với số lần xác định. Vòng lặp while lặp khi điều kiện còn đúng.\nfor...of duyệt các phần tử của mảng, for...in duyệt các khóa của đối tượng.\nbreak dùng để thoát vòng lặp, continue bỏ qua lần lặp hiện tại.',NULL,3,13),(4,1,'Hàm và phạm vi','Hàm là khối lệnh có thể tái sử dụng. Arrow function là cú pháp ngắn gọn.\nPhạm vi của biến let và const là phạm vi khối. Closure là hàm ghi nhớ biến của phạm vi bên ngoài.',NULL,4,29),(5,1,'Mảng và đối tượng','Mảng lưu danh sách giá trị có thứ tự. Phương thức map, filter, reduce giúp xử lý mảng.\nĐối tượng lưu dữ liệu dạng cặp khóa và giá trị. Destructuring giúp lấy giá trị nhanh.\nToán tử spread ... dùng để sao chép hoặc gộp mảng, đối tượng.',NULL,5,8),(6,1,'Promise và async/await','Promise đại diện cho kết quả của thao tác bất đồng bộ, có ba trạng thái pending, fulfilled và rejected.\nTừ khóa async và await giúp viết mã bất đồng bộ dễ đọc như mã đồng bộ. Lỗi được bắt bằng try catch.',NULL,6,19),(7,2,'Node.js là gì','Node.js là môi trường chạy JavaScript phía máy chủ dựa trên V8.\nNode.js sử dụng mô hình vào ra không chặn và vòng lặp sự kiện, phù hợp ứng dụng nhiều thao tác I/O.','https://www.youtube.com/watch?v=TlB_eWDSMt4',1,8),(8,2,'npm và module','npm là trình quản lý gói của Node.js. File package.json mô tả dự án và các thư viện phụ thuộc.\nES Modules dùng import và export để chia nhỏ mã nguồn.',NULL,2,23),(9,2,'Express và Routing','Express là framework web tối giản cho Node.js. Router giúp tách các nhóm đường dẫn.\nMiddleware xử lý request trước khi tới handler, ví dụ kiểm tra đăng nhập hoặc ghi log.',NULL,3,26),(10,2,'Thiết kế REST API','REST dùng phương thức HTTP GET, POST, PUT, DELETE để thao tác tài nguyên.\nMã trạng thái 200 thành công, 201 tạo mới, 400 dữ liệu sai, 401 chưa đăng nhập, 403 không có quyền, 404 không tìm thấy.',NULL,4,12),(11,2,'Xác thực với JWT','JSON Web Token gồm ba phần header, payload và signature.\nMáy chủ ký token khi đăng nhập và kiểm tra token ở mỗi request thông qua header Authorization.',NULL,5,12),(12,3,'Component và JSX','React xây dựng giao diện từ các component. JSX cho phép viết cú pháp giống HTML trong JavaScript.\nProps truyền dữ liệu từ component cha xuống component con.','https://www.youtube.com/watch?v=SqcY0GlETPk',1,22),(13,3,'State và useState','useState lưu trạng thái của component. Khi state thay đổi, component được render lại.\nKhông sửa state trực tiếp mà dùng hàm setState.',NULL,2,21),(14,3,'useEffect và gọi API','useEffect chạy hiệu ứng phụ như gọi API, đăng ký sự kiện.\nMảng phụ thuộc quyết định khi nào effect chạy lại. Hàm trả về dùng để dọn dẹp.',NULL,3,29),(15,3,'React Router','React Router quản lý điều hướng trong ứng dụng một trang.\nRoute ánh xạ đường dẫn tới component tương ứng, useParams đọc tham số trên URL.',NULL,4,20),(16,3,'Context và quản lý trạng thái','Context chia sẻ dữ liệu cho nhiều component mà không cần truyền props qua nhiều cấp.\nThường dùng cho thông tin đăng nhập, giao diện sáng tối, ngôn ngữ.',NULL,5,29),(17,4,'Mô hình quan hệ','Cơ sở dữ liệu quan hệ lưu dữ liệu trong các bảng. Khóa chính định danh duy nhất mỗi dòng.\nKhóa ngoại liên kết các bảng với nhau và đảm bảo toàn vẹn tham chiếu.',NULL,1,18),(18,4,'Truy vấn SELECT','Câu lệnh SELECT dùng để truy vấn dữ liệu. WHERE lọc dòng, ORDER BY sắp xếp, LIMIT giới hạn số dòng.',NULL,2,15),(19,4,'JOIN và GROUP BY','INNER JOIN kết hợp các dòng khớp ở hai bảng, LEFT JOIN giữ toàn bộ dòng bảng trái.\nGROUP BY nhóm dữ liệu để tính tổng hợp với COUNT, SUM, AVG. HAVING lọc sau khi nhóm.',NULL,3,13),(20,4,'Chuẩn hóa dữ liệu','Chuẩn hóa giúp loại bỏ dư thừa dữ liệu. 1NF yêu cầu giá trị nguyên tố, 2NF loại bỏ phụ thuộc bộ phận, 3NF loại bỏ phụ thuộc bắc cầu.',NULL,4,16),(21,4,'Chỉ mục và giao dịch','Chỉ mục giúp tăng tốc truy vấn. Giao dịch đảm bảo tính ACID: nguyên tố, nhất quán, cô lập, bền vững.',NULL,5,8),(22,5,'Cấu trúc HTML','HTML mô tả cấu trúc trang web bằng các thẻ. Thẻ ngữ nghĩa như header, nav, main, footer giúp trang dễ hiểu với trình đọc màn hình và SEO.',NULL,1,21),(23,5,'CSS cơ bản','CSS định dạng giao diện. Bộ chọn class, id, thẻ. Mô hình hộp gồm content, padding, border và margin.',NULL,2,20),(24,5,'Flexbox','Flexbox sắp xếp phần tử theo một chiều. justify-content căn theo trục chính, align-items căn theo trục phụ.',NULL,3,21),(25,5,'CSS Grid và Responsive','Grid sắp xếp bố cục hai chiều. Media query giúp giao diện thay đổi theo kích thước màn hình.',NULL,4,13),(26,6,'Git là gì','Git là hệ thống quản lý phiên bản phân tán. Mỗi commit là một ảnh chụp trạng thái dự án.',NULL,1,29),(27,6,'Các lệnh cơ bản','git init tạo kho, git add đưa thay đổi vào vùng chờ, git commit lưu lại, git status xem trạng thái, git log xem lịch sử.',NULL,2,20),(28,6,'Branch và merge','Branch cho phép phát triển tính năng độc lập. git merge gộp nhánh, xung đột cần được giải quyết thủ công.',NULL,3,20),(29,6,'GitHub và Pull Request','GitHub lưu kho từ xa. git push đẩy mã lên, pull request để đồng đội xem xét trước khi gộp.',NULL,4,17),(30,7,'Độ phức tạp thuật toán','Ký hiệu Big O mô tả tốc độ tăng của thời gian chạy theo kích thước đầu vào. O(1), O(log n), O(n), O(n log n), O(n^2).',NULL,1,24),(31,7,'Ngăn xếp và hàng đợi','Ngăn xếp hoạt động theo nguyên tắc LIFO, hàng đợi theo nguyên tắc FIFO.',NULL,2,9),(32,7,'Sắp xếp','Sắp xếp nổi bọt có độ phức tạp O(n^2). Sắp xếp trộn và sắp xếp nhanh trung bình O(n log n).',NULL,3,20),(33,7,'Tìm kiếm nhị phân','Tìm kiếm nhị phân trên mảng đã sắp xếp có độ phức tạp O(log n), mỗi bước loại bỏ một nửa số phần tử.',NULL,4,19),(34,7,'Cây và đồ thị','Cây nhị phân tìm kiếm cho phép tìm, thêm, xóa trung bình O(log n). Đồ thị duyệt bằng BFS và DFS.',NULL,5,11),(35,8,'Mô hình ngôn ngữ lớn','Mô hình ngôn ngữ lớn được huấn luyện trên lượng văn bản khổng lồ. Chúng có thể sinh văn bản, tóm tắt và trả lời câu hỏi.',NULL,1,29),(36,8,'Gọi API mô hình AI','Các nhà cung cấp như Groq, OpenAI, Gemini cung cấp REST API. Ứng dụng gửi prompt và nhận về văn bản hoặc JSON. API key phải được giữ bí mật ở máy chủ.',NULL,2,10),(37,8,'Prompt engineering','Prompt rõ ràng, có vai trò, ngữ cảnh và định dạng đầu ra cụ thể giúp mô hình trả lời chính xác hơn. Yêu cầu đầu ra JSON giúp dễ xử lý trong ứng dụng.',NULL,3,22),(38,8,'Đánh giá và an toàn','Kết quả AI có thể sai, cần con người kiểm duyệt với các quyết định quan trọng. Cần có phương án dự phòng khi dịch vụ AI lỗi.',NULL,4,24);
