INSERT INTO `quiz_questions` VALUES (1,1,'Từ khóa nào khai báo hằng số?','[\"var\",\"let\",\"const\",\"static\"]',2,'const khai báo biến không thể gán lại.'),(2,1,'Phương thức nào tạo mảng mới từ kết quả của hàm?','[\"forEach\",\"map\",\"push\",\"find\"]',1,'map trả về mảng mới.'),(3,1,'await chỉ dùng được trong?','[\"Mọi hàm\",\"Hàm async\",\"Vòng lặp for\",\"Constructor\"]',1,'await dùng trong hàm async (hoặc top-level module).'),(4,1,'typeof null trả về?','[\"\\\"null\\\"\",\"\\\"undefined\\\"\",\"\\\"object\\\"\",\"\\\"number\\\"\"]',2,'Đây là một đặc điểm lịch sử của JavaScript.'),(5,1,'Toán tử nào so sánh cả kiểu dữ liệu?','[\"==\",\"===\",\"=\",\"!=\"]',1,'=== là so sánh nghiêm ngặt.'),(6,2,'Node.js chạy trên engine nào?','[\"SpiderMonkey\",\"V8\",\"Chakra\",\"JVM\"]',1,'Node.js dùng V8 của Google.'),(7,2,'Mã trạng thái khi tạo mới thành công?','[\"200\",\"201\",\"204\",\"301\"]',1,'201 Created.'),(8,2,'Middleware trong Express nhận mấy tham số chính?','[\"1\",\"2\",\"3 (req, res, next)\",\"5\"]',2,'Middleware có dạng (req, res, next).'),(9,2,'JWT gồm mấy phần?','[\"2\",\"3\",\"4\",\"5\"]',1,'header.payload.signature'),(10,3,'Hook nào dùng để lưu trạng thái?','[\"useEffect\",\"useState\",\"useRef\",\"useMemo\"]',1,'useState lưu state.'),(11,3,'Props truyền dữ liệu theo chiều nào?','[\"Con → cha\",\"Cha → con\",\"Hai chiều\",\"Không truyền được\"]',1,'Dữ liệu một chiều từ cha xuống con.'),(12,3,'Hook đọc tham số URL trong React Router?','[\"useParams\",\"useState\",\"useUrl\",\"useRoute\"]',0,'useParams trả về các tham số động.'),(13,3,'JSX được biên dịch thành?','[\"HTML\",\"Lời gọi React.createElement / jsx()\",\"CSS\",\"JSON\"]',1,'JSX là cú pháp đường.'),(14,4,'Lệnh nào dùng để truy vấn dữ liệu?','[\"INSERT\",\"SELECT\",\"UPDATE\",\"DROP\"]',1,'SELECT đọc dữ liệu.'),(15,4,'LEFT JOIN giữ lại?','[\"Chỉ dòng khớp\",\"Toàn bộ bảng trái\",\"Toàn bộ bảng phải\",\"Không dòng nào\"]',1,'LEFT JOIN giữ mọi dòng bảng trái.'),(16,4,'Mệnh đề lọc sau GROUP BY?','[\"WHERE\",\"HAVING\",\"ORDER BY\",\"LIMIT\"]',1,'HAVING lọc nhóm.'),(17,4,'ACID chữ I nghĩa là?','[\"Index\",\"Isolation (cô lập)\",\"Insert\",\"Integer\"]',1,'Isolation.'),(18,5,'Thẻ nào là thẻ ngữ nghĩa?','[\"div\",\"span\",\"article\",\"b\"]',2,'article có ý nghĩa nội dung.'),(19,5,'Thuộc tính căn theo trục chính trong Flexbox?','[\"align-items\",\"justify-content\",\"flex-wrap\",\"gap\"]',1,'justify-content.'),(20,5,'Media query dùng để?','[\"Phát video\",\"Thiết kế responsive\",\"Nhúng font\",\"Tạo animation\"]',1,'Thay đổi giao diện theo màn hình.'),(21,6,'Lệnh lưu thay đổi vào lịch sử?','[\"git add\",\"git commit\",\"git push\",\"git status\"]',1,'git commit.'),(22,6,'Lệnh đẩy mã lên kho từ xa?','[\"git pull\",\"git fetch\",\"git push\",\"git clone\"]',2,'git push.'),(23,6,'Pull request dùng để?','[\"Xóa nhánh\",\"Đề nghị gộp mã và review\",\"Tạo kho\",\"Hoàn tác commit\"]',1,'Review trước khi merge.'),(24,7,'Độ phức tạp tìm kiếm nhị phân?','[\"O(n)\",\"O(log n)\",\"O(n^2)\",\"O(1)\"]',1,'Mỗi bước chia đôi.'),(25,7,'Ngăn xếp hoạt động theo nguyên tắc?','[\"FIFO\",\"LIFO\",\"Ngẫu nhiên\",\"Ưu tiên\"]',1,'Last In First Out.'),(26,7,'Thuật toán duyệt đồ thị theo chiều rộng?','[\"DFS\",\"BFS\",\"Dijkstra\",\"Kruskal\"]',1,'Breadth First Search.'),(27,8,'API key của AI nên lưu ở đâu?','[\"Mã nguồn frontend\",\"Biến môi trường phía server\",\"LocalStorage\",\"Đăng lên GitHub\"]',1,'Giữ bí mật ở server.'),(28,8,'Yêu cầu đầu ra JSON giúp?','[\"AI chạy nhanh hơn\",\"Dễ xử lý kết quả trong ứng dụng\",\"Giảm giá\",\"Không có tác dụng\"]',1,'Dữ liệu có cấu trúc.'),(29,8,'Khi dịch vụ AI lỗi nên?','[\"Dừng hệ thống\",\"Có phương án dự phòng\",\"Báo lỗi 500 mãi\",\"Xóa dữ liệu\"]',1,'Fallback.');
