INSERT INTO `submissions` VALUES (1,2,3,'Có thể nói ví dụ gần như đáng nhớ nhờ cả lớp học demo tháng rồi, em thấy vậy. Thực tế khai báo lại rất hữu ích vì mọi người sửa module gần đây, em nghĩ thế. Thực tế khai báo lại chắc chắn dễ nhầm bởi nhóm em xem bài tập kỳ này, em nghĩ thế. Theo em gán lại giá trị gần như mới mẻ nếu tụi em học bài lab ở nhà, em đoán vậy. Đầu tiên hoisting đôi khi cơ bản do chúng em debug project trên lớp, nói chung. Tiếp theo gán lại giá trị luôn cần thiết nhờ cả lớp học trang quản trị hôm qua, đại khái thế. Em nghĩ hoisting phần lớn mới mẻ dù cả lớp làm ứng dụng trên lớp, em thấy vậy. Thực tế gán lại giá trị luôn hữu ích lúc người mới dựng mini game buổi tối, theo kinh nghiệm. Trước hết ví dụ khá dễ nhầm vì em đọc bài lab ở nhà, em đoán vậy.',7.00,6.30,'{\"feedback\":\"Bài làm có 170 từ, bao quát 2/6 ý chính trong tiêu chí chấm.\",\"strengths\":[\"Bài viết có độ dài đầy đủ.\",\"Đề cập tới: hoisting, khai.\"],\"improvements\":[\"Nên bổ sung các nội dung: phạm, khối, sánh, const.\"],\"provider\":\"mock\"}','Nội dung còn sơ sài.',17.11,4,'graded','2026-10-12 08:42:00','2026-10-13 00:40:00'),(2,2,8,'Có thể nói hoisting thật sự mới mẻ khi bạn em dựng ứng dụng kỳ này, em thấy vậy. Em nghĩ phạm vi khối thật sự khó hiểu vì tụi em ôn demo ở nhà, em thấy vậy.',4.00,3.90,'{\"feedback\":\"Bài làm có 38 từ, bao quát 3/6 ý chính trong tiêu chí chấm.\",\"strengths\":[\"Bài viết ngắn gọn.\",\"Đề cập tới: phạm, khối, hoisting.\"],\"improvements\":[\"Nên bổ sung các nội dung: khai, sánh, const.\"],\"provider\":\"mock\"}','Trình bày rõ ràng, đủ ý.',28.14,5,'graded','2026-10-10 13:07:00','2026-10-11 03:52:00'),(3,2,25,'Rõ ràng ví dụ phần lớn cơ bản nhờ người mới dựng bài thi tháng rồi, em đoán vậy. Bên cạnh đó gán lại giá trị thật sự phức tạp lúc tụi em dựng API kỳ này, em nghĩ thế. Hiểu đơn giản ví dụ luôn hữu ích do em làm đồ án năm ngoái, em thấy vậy. Có thể nói gán lại giá trị khá then chốt dù mọi người test trang quản trị gần đây, em đoán vậy.',2.40,2.40,'{\"feedback\":\"Bài làm có 80 từ, bao quát 0/6 ý chính trong tiêu chí chấm.\",\"strengths\":[\"Bài viết ngắn gọn.\",\"Có nỗ lực hoàn thành bài.\"],\"improvements\":[\"Nên bổ sung các nội dung: phạm, khối, hoisting, khai, sánh.\"],\"provider\":\"mock\"}',NULL,24.03,4,'ai_graded','2026-10-12 00:36:00',NULL),(4,2,28,'Hiểu đơn giản hoisting luôn cần thiết bởi người mới thử demo ở nhà, nói chung. Theo em khai báo lại chắc chắn thú vị bởi bạn em làm đồ án tháng rồi, em đoán vậy. Trước hết khai báo lại phần lớn thú vị dù người mới thử module gần đây, em đoán vậy. Theo em phạm vi khối thường phổ biến dù tụi em sửa project hôm qua, em nghĩ thế. Trước hết gán lại giá trị thật sự quan trọng bởi chúng em chạy bài lab tuần trước, nói chung. Trước hết phạm vi khối luôn quan trọng bởi cả lớp dựng bài thi buổi tối, đại khái thế. Thực tế hoisting rất cần thiết khi tụi em debug demo tháng rồi, em nghĩ thế. Có thể nói gán lại giá trị khá cần thiết nếu mọi người đọc đồ án năm ngoái, đúng không ạ. Đầu tiên ví dụ chắc chắn mới mẻ bởi mọi người xem bài thi trên lớp, nói chung. Theo em gán lại giá trị đôi khi thú vị dù người mới xem trang quản trị ở nhà, theo kinh nghiệm. Thực tế khai báo lại rất phổ biến vì chúng em debug ứng dụng trên lớp, đại khái thế. Theo em ví dụ đôi khi hữu ích do bạn em xem website tháng rồi, nói chung. Theo em ví dụ thật sự khó hiểu bởi mọi người viết module năm ngoái, về cơ bản. Sau cùng hoisting rất cơ bản nếu chúng em đọc website tuần trước, nói chung.',8.00,8.20,'{\"feedback\":\"Bài làm có 258 từ, bao quát 4/6 ý chính trong tiêu chí chấm.\",\"strengths\":[\"Bài viết có độ dài đầy đủ.\",\"Đề cập tới: phạm, khối, hoisting, khai.\"],\"improvements\":[\"Nên bổ sung các nội dung: sánh, const.\"],\"provider\":\"mock\"}','Trình bày rõ ràng, đủ ý.',15.86,5,'graded','2026-10-11 13:12:00','2026-10-12 08:33:00'),(5,2,31,'Rõ ràng khai báo lại hẳn thú vị nhờ tụi em debug đồ án gần đây, về cơ bản. Hiểu đơn giản khai báo lại phần lớn then chốt lúc tụi em dựng website tuần trước, đúng không ạ. Nhìn chung phạm vi khối thật sự khó hiểu vì tụi em ôn website tuần trước, em đoán vậy. Em nghĩ hoisting thường then chốt nhờ cả lớp xem trang quản trị tháng rồi, nói chung. Bên cạnh đó ví dụ thường phức tạp nhờ nhóm em xem ứng dụng buổi tối, theo kinh nghiệm. Nhìn chung gán lại giá trị thường hữu ích lúc bạn em test đồ án cuối tuần, về cơ bản. Bên cạnh đó gán lại giá trị đôi khi khó hiểu vì tụi em ôn API trên lớp, em đoán vậy. Em nghĩ hoisting thường mới mẻ bởi chúng em viết demo tuần trước, em thấy vậy. Thực tế phạm vi khối phần lớn then chốt vì cả lớp đọc trang quản trị trên lớp, em thấy vậy. Theo em phạm vi khối đôi khi khó hiểu nếu mọi người debug ứng dụng cuối tuần, em thấy vậy. Sau cùng ví dụ thường phổ biến vì người mới xem bài tập trên lớp, đại khái thế.',9.50,8.20,'{\"feedback\":\"Bài làm có 210 từ, bao quát 4/6 ý chính trong tiêu chí chấm.\",\"strengths\":[\"Bài viết có độ dài đầy đủ.\",\"Đề cập tới: phạm, khối, hoisting, khai.\"],\"improvements\":[\"Nên bổ sung các nội dung: sánh, const.\"],\"provider\":\"mock\"}','Cần thêm ví dụ minh họa.',18.22,4,'graded','2026-10-13 03:31:00','2026-10-14 03:42:00'),(6,2,43,'Mặt khác gán lại giá trị khá cần thiết khi chúng em xem trang quản trị gần đây, em thấy vậy. Sau cùng khai báo lại thật sự hữu ích lúc nhóm em sửa bài tập trên lớp, đại khái thế. Rõ ràng khai báo lại luôn đáng nhớ do bạn em thử ứng dụng gần đây, em thấy vậy. Cụ thể phạm vi khối thường cần thiết bởi mọi người thử trang quản trị năm ngoái, về cơ bản. Rõ ràng phạm vi khối phần lớn cần thiết vì người mới đọc bài lab ở nhà, theo kinh nghiệm.',6.00,5.80,'{\"feedback\":\"Bài làm có 100 từ, bao quát 3/6 ý chính trong tiêu chí chấm.\",\"strengths\":[\"Bài viết ngắn gọn.\",\"Đề cập tới: phạm, khối, khai.\"],\"improvements\":[\"Nên bổ sung các nội dung: hoisting, sánh, const.\"],\"provider\":\"mock\"}','Bài làm tốt.',19.75,4,'graded','2026-10-12 04:12:00','2026-10-13 08:58:00'),(7,2,47,'Hiểu đơn giản hoisting hẳn phức tạp dù cả lớp thử bài thi cuối tuần, em nghĩ thế. Nhìn chung phạm vi khối chắc chắn cần thiết nhờ nhóm em viết website trên lớp, nói chung. Sau cùng ví dụ đôi khi cơ bản khi chúng em sửa module buổi tối, em nghĩ thế. Bên cạnh đó hoisting hẳn thú vị dù em ôn ứng dụng tuần trước, em thấy vậy. Có thể nói khai báo lại hẳn phổ biến khi nhóm em debug bài tập kỳ này, đại khái thế. Đầu tiên hoisting rất then chốt nhờ mọi người đọc bài lab cuối tuần, theo kinh nghiệm. Hiểu đơn giản phạm vi khối luôn then chốt khi mọi người debug website hôm qua, nói chung. Theo em ví dụ gần như khó hiểu dù em chạy API buổi tối, về cơ bản. Bên cạnh đó phạm vi khối gần như quan trọng dù bạn em học bài tập buổi tối, em thấy vậy. Thực tế khai báo lại hẳn khó hiểu dù em dựng bài tập cuối tuần, theo kinh nghiệm.',8.50,8.20,'{\"feedback\":\"Bài làm có 182 từ, bao quát 4/6 ý chính trong tiêu chí chấm.\",\"strengths\":[\"Bài viết có độ dài đầy đủ.\",\"Đề cập tới: phạm, khối, hoisting, khai.\"],\"improvements\":[\"Nên bổ sung các nội dung: sánh, const.\"],\"provider\":\"mock\"}','Bài làm tốt.',16.05,5,'graded','2026-10-07 09:39:00','2026-10-08 11:02:00'),(8,3,3,'Hiểu đơn giản middleware chắc chắn quan trọng nếu em dựng đồ án tuần trước, đúng không ạ. Thực tế middleware thật sự mới mẻ bởi nhóm em test bài tập buổi tối, về cơ bản. Bên cạnh đó phương thức GET POST PUT DELETE khá khó hiểu lúc nhóm em xem module kỳ này, em nghĩ thế. Thực tế phương thức GET POST PUT DELETE rất then chốt vì cả lớp học ứng dụng kỳ này, theo kinh nghiệm. Mặt khác mã trạng thái HTTP gần như thú vị nhờ mọi người làm ứng dụng gần đây, đúng không ạ. Đầu tiên Endpoint CRUD thật sự dễ nhầm nếu bạn em viết bài thi tháng rồi, em đoán vậy. Thực tế xác thực JWT thường dễ nhầm dù em đọc đồ án trên lớp, em nghĩ thế. Thực tế mã trạng thái HTTP thật sự dễ nhầm lúc cả lớp ôn project tháng rồi, theo kinh nghiệm. Cụ thể Endpoint CRUD phần lớn dễ nhầm bởi bạn em thử mini game gần đây, theo kinh nghiệm. Mặt khác phương thức GET POST PUT DELETE thật sự then chốt vì bạn